</style></head><body><main>${content}</main></body></html>`;
}

function projectList(error = '', value = '') {
  const projects = listProjects.all();
  return page('Projects', `<h1>Workboard</h1>
<form method="post" action="/projects">
<label for="project-name">Project name</label>
<div class="create"><input id="project-name" name="name" value="${escapeHtml(value)}" type="text"><button type="submit">Create project</button></div>
${error ? `<p role="alert">${escapeHtml(error)}</p>` : ''}
</form>
${projects.length ? `<ul>${projects.map(project => `<li data-testid="project-row"><span>${escapeHtml(project.name)}</span><form method="get" action="/projects/${project.id}"><button type="submit">Open project</button></form></li>`).join('')}</ul>` : '<p>No projects yet.</p>'}`);
}

function sendHtml(res, status, html) {
  res.writeHead(status, { 'Content-Type': 'text/html; charset=utf-8', 'Cache-Control': 'no-store' });
  res.end(html);
}

const server = http.createServer(async (req, res) => {
  try {
    const url = new URL(req.url, 'http://localhost');
    if (req.method === 'GET' && url.pathname === '/health') {
      res.writeHead(200, { 'Content-Type': 'application/json' });
      return res.end(JSON.stringify({ status: 'ok' }));
    }
    if (req.method === 'GET' && url.pathname === '/') {
      return sendHtml(res, 200, projectList());
    }
    if (req.method === 'POST' && url.pathname === '/projects') {
      const chunks = [];
      let size = 0;
      for await (const chunk of req) {
        size += chunk.length;
        if (size > 1024 * 1024) {
          return sendHtml(res, 413, page('Request too large', '<h1>Request too large</h1>'));
        }
        chunks.push(chunk);
      }
      const name = (new URLSearchParams(Buffer.concat(chunks).toString()).get('name') || '').trim();
      if (!name) return sendHtml(res, 400, projectList('Project name is required'));
      addProject.run(name);
      res.writeHead(303, { Location: '/' });
      return res.end();
    }
    const match = url.pathname.match(/^\/projects\/([1-9]\d*)$/);
    if (req.method === 'GET' && match) {
      const project = getProject.get(match[1]);
      if (project) return sendHtml(res, 200, page(project.name, `<h1>${escapeHtml(project.name)}</h1><form method="get" action="/"><button type="submit">Projects</button></form>`));
    }
    sendHtml(res, 404, page('Not found', '<h1>Not found</h1><a href="/">Projects</a>'));
  } catch (error) {
    console.error(error);
    if (!res.headersSent) sendHtml(res, 500, page('Server error', '<h1>Server error</h1>'));
    else res.end();
  }
});

server.listen(Number(process.env.PORT || 8080), '0.0.0.0', () => {
  console.log(`Workboard listening on port ${server.address().port}`);
});

for (const signal of ['SIGINT', 'SIGTERM']) {
  process.on(signal, () => server.close(() => { db.close(); process.exit(0); }));
}

